package vn.edu.eaut.lab8.bean; import jakarta.enterprise.context.SessionScoped;import jakarta.inject.Named;import jakarta.faces.application.FacesMessage;import jakarta.faces.context.FacesContext;import java.io.Serializable; @Named("loginBean")@SessionScoped public class LoginBean implements Serializable {private String username,password;public String login(){if(("admin".equals(username)||"user".equals(username))&&"123456".equals(password))return "index?faces-redirect=true";FacesContext.getCurrentInstance().addMessage(null,new FacesMessage(FacesMessage.SEVERITY_ERROR,"Lỗi","Sai tài khoản hoặc mật khẩu"));return null;}public String getUsername(){return username;}public void setUsername(String v){username=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}}
